    def mostCommonWord(self, paragraph, banned):
        """
        :type paragraph: str
        :type banned: List[str]
        :rtype: str
        """
        banned = set(banned)
        freq = collections.defaultdict(int)
        cur_word = ""
        for c in paragraph:
            if c.isalpha():
                cur_word += c.lower()
            else:
                if cur_word and cur_word not in banned:
                    freq[cur_word] += 1
                cur_word = ""
        if cur_word and cur_word not in banned:
            freq[cur_word] += 1
        return list(sorted(freq.items(), key=lambda x: x[1], reverse=True))[0][0]
